// Round-2 regression tests for the session member gate: the validators' probes on CLIProxyAPI #10 at efbc6c91
// (a234/W-1, regenerated by a238; validator-evidence/a234/cliproxy-pr10/evidence/r2_a234_gate_test.go and
// r2_v2g_additions_test.go), kept as written apart from names and formatting. R2-1: with response steering on, every
// websocket frame the duplex path accepts still passes the gate. R2-2: a nested duplicate key cannot make the gate and
// the image stripper read different tool types. R2-3: stripping the image tool leaves a satisfiable tool_choice. R2-4:
// every route runs the strict body check on the raw body, before any conversion. The other tests are controls that
// already held. All identities, credentials, upstreams and bodies are fake and stay on loopback.

func r2Decoded(t *testing.T, raw []byte) map[string]any {
	t.Helper()
	var v map[string]any
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	return v
}

func TestSessionMemberGateR2NestedDuplicateToolType(t *testing.T) {
	for _, path := range []string{"/v1/responses", "/backend-api/codex/responses", "/v1/responses/compact", "/backend-api/codex/responses/compact"} {
		for _, escaped := range []bool{false, true} {
			t.Run(fmt.Sprintf("%s/escaped_%t", path, escaped), func(t *testing.T) {
				h := newMemberGateHarness(t, true)
				u := useRealExecutor(t, h, "codex")
				key := `"type"`
				if escaped {
					key = `"\u0074ype"`
				}
				body := `{"model":"gpt-6-astra","input":"hi","tools":[{"type":"web_search",` + key + `:"image_generation","model":"gpt-image-2"}]}`
				r := h.do(t, http.MethodPost, path, codexSessionToken, body)
				leaked := false
				for _, raw := range u.received() {
					v := r2Decoded(t, raw)
					if tools, ok := v["tools"].([]any); ok {
						for _, tool := range tools {
							if m, ok := tool.(map[string]any); ok && m["type"] == "image_generation" {
								leaked = true
							}
						}
					}
				}
				t.Logf("HTTP=%d upstream-calls=%d decoded-image-tool-forwarded=%t", r.Code, len(u.received()), leaked)
				if leaked {
					t.Error("duplicate nested type defeats final image stripping")
				}
			})
		}
	}
}

func TestSessionMemberGateR2StrippingLeavesUsableToolChoice(t *testing.T) {
	for _, choice := range []string{`"required"`, `{"type":"image_generation"}`, `{"type":"allowed_tools","mode":"required","tools":[{"type":"image_generation"}]}`} {
		for _, stream := range []bool{false, true} {
			t.Run(fmt.Sprintf("%s/stream_%t", choice, stream), func(t *testing.T) {
				h := newMemberGateHarness(t, true)
				u := useRealExecutor(t, h, "codex")
				original := u.server.Config.Handler
				var mu sync.Mutex
				invalid := false
				u.server.Config.Handler = http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
					raw, _ := io.ReadAll(r.Body)
					v := r2Decoded(t, raw)
					r.Body = io.NopCloser(bytes.NewReader(raw))
					tools, _ := v["tools"].([]any)
					tc := v["tool_choice"]
					bad := len(tools) == 0 && tc == "required"
					if m, ok := tc.(map[string]any); ok && m["type"] == "allowed_tools" {
						bad = true
					}
					if bad {
						mu.Lock()
						invalid = true
						mu.Unlock()
						http.Error(w, `{"error":{"message":"fake provider: required tool_choice has no available tool"}}`, 400)
						return
					}
					original.ServeHTTP(w, r)
				})
				body := fmt.Sprintf(`{"model":"gpt-6-astra","input":"hi","tools":[{"type":"image_generation"}],"tool_choice":%s,"stream":%t}`, choice, stream)
				r := h.do(t, http.MethodPost, "/v1/responses", codexSessionToken, body)
				mu.Lock()
				bad := invalid
				mu.Unlock()
				t.Logf("HTTP=%d dangling-choice=%t", r.Code, bad)
				if bad || r.Code != 200 {
					t.Error("stripped image request retains an unsatisfiable tool choice")
				}
			})
		}
	}
}

func TestSessionMemberGateR2NeutralNestedFieldsKeepMember(t *testing.T) {
	for _, extra := range []string{
		`"metadata":{"model":"gpt-5.5-codex","nested":{"model":"gpt-5.5-codex"}}`,
		`"reasoning":{"effort":"low","model":"gpt-5.5-codex"}`,
		`"input":[{"role":"user","content":"hi","model":"gpt-5.5-codex"}]`,
		`"tools":[{"type":"function","name":"f","parameters":{"type":"object","properties":{"model":{"type":"string","default":"gpt-5.5-codex"}}}}]`,
	} {
		for _, path := range []string{"/v1/responses", "/backend-api/codex/responses"} {
			t.Run(path+"/"+extra, func(t *testing.T) {
				h := newMemberGateHarness(t, true)
				u := useRealExecutor(t, h, "codex")
				body := `{"model":"gpt-6-astra",` + extra + `}`
				r := h.do(t, http.MethodPost, path, codexSessionToken, body)
				if r.Code != 200 {
					t.Fatalf("neutral-field control HTTP=%d", r.Code)
				}
				if len(u.received()) != 1 {
					t.Fatal("neutral-field control did not execute")
				}
				for _, raw := range u.received() {
					if r2Decoded(t, raw)["model"] != "gpt-6-astra" {
						t.Error("nested inert field changed the selected model")
					}
				}
			})
		}
	}
}

func TestSessionMemberGateR2StrictRootVariants(t *testing.T) {
	for _, extra := range []string{
		`"\u006dodel":"gpt-5.5-codex"`,
		`"MODEL":"gpt-6-astra"`,
		`"metadata":{},"\u006detadata":{"model":"gpt-5.5-codex"}`,
		`"tools":[],"\u0074ools":[{"type":"image_generation"}]`,
	} {
		for _, path := range []string{"/v1/responses", "/v1/chat/completions", "/v1/completions", "/backend-api/codex/responses"} {
			t.Run(path+"/"+extra, func(t *testing.T) {
				h := newMemberGateHarness(t, true)
				body := `{"model":"gpt-6-astra","input":"hi","prompt":"hi","messages":[{"role":"user","content":"hi"}],` + extra + `}`
				r := h.do(t, http.MethodPost, path, codexSessionToken, body)
				n := len(h.codex.calls()) + len(h.claude.calls())
				t.Logf("HTTP=%d executor-calls=%d", r.Code, n)
				if r.Code < 400 || n != 0 {
					t.Error("strict root decoder did not reject repeated decoded keys")
				}
			})
		}
	}
}

func TestSessionMemberGateR2WebsocketAppendAndOtherFrames(t *testing.T) {
	for _, path := range []string{"/v1/responses", "/backend-api/codex/responses"} {
		t.Run(path, func(t *testing.T) {
			h := newMemberGateHarness(t, true)
			u := useRealExecutor(t, h, "codex")
			mode := memberGateKubeMode(h)
			c := dialMemberGateWebsocket(t, h, path, codexSessionToken)
			send := func(s string) {
				t.Helper()
				if err := c.WriteMessage(websocket.TextMessage, []byte(s)); err != nil {
					t.Fatal(err)
				}
			}
			send(`{"type":"response.create","model":"gpt-6-astra","input":[]}`)
			if v := nextTerminalEvent(t, c); gjson.GetBytes(v, "type").String() != "response.completed" {
				t.Fatal("initial member frame did not run")
			}
			for _, frame := range []string{
				`{"type":"response.append","model":"gpt-5.5-codex","input":[]}`,
				`{"type":"response.steer","model":"gpt-5.5-codex","input":"hi"}`,
				`{"type":"session.update","session":{"model":"gpt-5.5-codex"}}`,
				`{"type":"conversation.item.create","item":{"model":"gpt-5.5-codex"}}`,
				`{"type":"response.cancel","model":"gpt-5.5-codex"}`,
			} {
				send(frame)
				v := nextTerminalEvent(t, c)
				if gjson.GetBytes(v, "type").String() != "error" || len(u.received()) != 1 {
					t.Fatalf("other frame reached upstream: %s", v)
				}
			}
			mode.Store("expired")
			send(`{"type":"response.append","model":"gpt-6-astra","input":[]}`)
			v := nextTerminalEvent(t, c)
			if gjson.GetBytes(v, "status").Int() != 403 || len(u.received()) != 1 {
				t.Fatalf("append after revoked identity: %s", v)
			}
		})
	}
}

func TestSessionMemberGateR2DuplexFramesStillApplyTheGate(t *testing.T) {
	for _, tc := range []struct{ name, mode, frame string }{
		{"revoked_create", "expired", `{"type":"response.create","model":"gpt-6-astra","input":[]}`},
		{"revoked_append", "expired", `{"type":"response.append","model":"gpt-6-astra","input":[]}`},
		{"duplicate_model", "", `{"type":"response.create","model":"gpt-6-astra","model":"gpt-5.5-codex","input":[]}`},
		{"stored_prompt", "", `{"type":"response.create","model":"gpt-6-astra","input":[],"prompt":{"id":"pmpt_fake"}}`},
		{"tool_model", "", `{"type":"response.create","model":"gpt-6-astra","input":[],"tools":[{"type":"web_search","model":"gpt-5.5-codex"}]}`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			h := newMemberGateHarness(t, true)
			mode := memberGateKubeMode(h)
			h.server.cfg.Codex.ResponseSteering = true
			h.server.cfg.CodexResponseSteering = true
			h.server.handlers.Cfg.CodexResponseSteering = true
			var mu sync.Mutex
			var frames [][]byte
			upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				c, err := (&websocket.Upgrader{}).Upgrade(w, r, nil)
				if err != nil {
					t.Error(err)
					return
				}
				defer c.Close()
				c.SetReadDeadline(time.Now().Add(10 * time.Second))
				for n := 1; ; n++ {
					_, p, err := c.ReadMessage()
					if err != nil {
						return
					}
					mu.Lock()
					frames = append(frames, append([]byte(nil), p...))
					mu.Unlock()
					c.WriteMessage(websocket.TextMessage, []byte(fmt.Sprintf(`{"type":"response.created","response":{"id":"r%d","output":[]}}`, n)))
					c.WriteMessage(websocket.TextMessage, []byte(fmt.Sprintf(`{"type":"response.completed","response":{"id":"r%d","output":[]}}`, n)))
				}
			}))
			defer upstream.Close()
			h.server.handlers.AuthManager.RegisterExecutor(runtimeexec.NewCodexAutoExecutor(h.server.cfg))
			if _, err := h.server.handlers.AuthManager.Register(context.Background(), &auth.Auth{ID: "member-gate-codex", Provider: "codex", Status: auth.StatusActive, Attributes: map[string]string{"api_key": "A234_FAKE_UPSTREAM_KEY", "base_url": upstream.URL, "websockets": "true"}}); err != nil {
				t.Fatal(err)
			}
			c := dialMemberGateWebsocket(t, h, "/v1/responses", codexSessionToken)
			c.WriteMessage(websocket.TextMessage, []byte(`{"type":"response.create","model":"gpt-6-astra","input":[]}`))
			if v := nextTerminalEvent(t, c); gjson.GetBytes(v, "type").String() != "response.completed" {
				t.Fatalf("initial frame failed: %s", v)
			}
			beforeReviews, beforePods := h.kube.reviews.Load(), h.kube.podReads.Load()
			mode.Store(tc.mode)
			c.WriteMessage(websocket.TextMessage, []byte(tc.frame))
			v := nextTerminalEvent(t, c)
			mu.Lock()
			got := append([][]byte(nil), frames...)
			mu.Unlock()
			lastModel := ""
			if len(got) > 1 {
				lastModel, _ = r2Decoded(t, got[len(got)-1])["model"].(string)
			}
			t.Logf("second-event=%s status=%d upstream-frames=%d decoded-last-model=%s new-reviews=%d new-pod-reads=%d", gjson.GetBytes(v, "type"), gjson.GetBytes(v, "status").Int(), len(got), lastModel, h.kube.reviews.Load()-beforeReviews, h.kube.podReads.Load()-beforePods)
			if len(got) > 1 || gjson.GetBytes(v, "status").Int() != 403 {
				t.Error("duplex continuation skipped the member gate")
			}
		})
	}
}

func TestSessionMemberGateR2ReviewCallCost(t *testing.T) {
	h := newMemberGateHarness(t, true)
	for i := 0; i < 20; i++ {
		r := h.do(t, http.MethodPost, "/v1/messages", claudeSessionToken, claudeMessage("claude-opus-5-5"))
		if r.Code != 200 {
			t.Fatal(r.Code)
		}
	}
	t.Logf("20 HTTP requests: reviews=%d pod-reads=%d", h.kube.reviews.Load(), h.kube.podReads.Load())
	if h.kube.reviews.Load() != 20 || h.kube.podReads.Load() != 20 {
		t.Fatal("unexpected identity API cost")
	}
	beforeR, beforeP := h.kube.reviews.Load(), h.kube.podReads.Load()
	if r := h.do(t, http.MethodGet, "/v1/models", memberGatePlainKey, ""); r.Code != 200 {
		t.Fatal(r.Code)
	}
	if h.kube.reviews.Load() != beforeR || h.kube.podReads.Load() != beforeP {
		t.Fatal("readiness incurred TokenReview traffic")
	}
}

// R2-2 over the websocket path (steering off): a nested duplicate tool type must not reach the upstream.
func TestSessionMemberGateR2WebsocketNestedDuplicateToolType(t *testing.T) {
	for _, path := range []string{"/v1/responses", "/backend-api/codex/responses"} {
		t.Run(path, func(t *testing.T) {
			h := newMemberGateHarness(t, true)
			u := useRealExecutor(t, h, "codex")
			c := dialMemberGateWebsocket(t, h, path, codexSessionToken)
			defer c.Close()
			body := `{"type":"response.create","model":"gpt-6-astra","input":[],"tools":[{"type":"web_search","type":"image_generation","model":"gpt-image-2"}]}`
			if err := c.WriteMessage(websocket.TextMessage, []byte(body)); err != nil {
				t.Fatal(err)
			}
			_ = c.SetReadDeadline(time.Now().Add(5 * time.Second))
			for {
				_, b, err := c.ReadMessage()
				if err != nil {
					break
				}
				kind := gjson.GetBytes(b, "type").String()
				if kind == "error" || kind == "response.completed" {
					break
				}
			}
			leaked := false
			for _, raw := range u.received() {
				v := r2Decoded(t, raw)
				if tools, ok := v["tools"].([]any); ok {
					for _, tool := range tools {
						if m, ok := tool.(map[string]any); ok && m["type"] == "image_generation" {
							leaked = true
						}
					}
				}
			}
			t.Logf("upstream-calls=%d decoded-image-tool-forwarded=%t", len(u.received()), leaked)
			if leaked {
				t.Error("websocket nested duplicate type defeats final image stripping")
			}
		})
	}
}

// R2-4 streaming variant: /v1/completions with stream:true must still refuse duplicate decoded keys.
func TestSessionMemberGateR2LegacyCompletionsStreamStrict(t *testing.T) {
	for _, extra := range []string{
		`"model":"gpt-5.5-codex"`,
		`"metadata":{},"metadata":{"model":"gpt-5.5-codex"}`,
		`"tools":[],"tools":[{"type":"image_generation"}]`,
	} {
		t.Run(extra, func(t *testing.T) {
			h := newMemberGateHarness(t, true)
			body := `{"model":"gpt-6-astra","prompt":"hi","stream":true,` + extra + `}`
			r := h.do(t, http.MethodPost, "/v1/completions", codexSessionToken, body)
			n := len(h.codex.calls()) + len(h.claude.calls())
			t.Logf("HTTP=%d executor-calls=%d", r.Code, n)
			if r.Code < 400 || n != 0 {
				t.Error("streaming legacy completions skipped the strict root decoder")
			}
		})
	}
}

