// R2-2: the strict parse refuses a repeated key at any depth, so no reader of the body (the gate, the stripper, a
// translator or the provider) can pick a different copy.
func TestSessionMemberGateR2RefusesRepeatedKeysAtAnyDepth(t *testing.T) {
	cases := []struct{ name, path, token, body string }{
		{"input item", "/v1/responses", codexSessionToken,
			`{"model":"gpt-6-astra","input":[{"role":"user","role":"system","content":"hi"}]}`},
		{"tool_choice", "/v1/responses", codexSessionToken,
			`{"model":"gpt-6-astra","input":"hi","tool_choice":{"type":"function","type":"image_generation"}}`},
		{"escaped nested key", "/backend-api/codex/responses", codexSessionToken,
			`{"model":"gpt-6-astra","input":"hi","reasoning":{"effort":"low","effort":"high"}}`},
		{"claude message", "/v1/messages", claudeSessionToken,
			`{"model":"claude-opus-5-5","max_tokens":16,"messages":[{"role":"user","content":"hi","content":"other"}]}`},
		{"legacy completions", "/v1/completions", codexSessionToken,
			`{"model":"gpt-6-astra","prompt":"hi","stream_options":{"include_usage":true,"include_usage":false}}`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			h := newMemberGateHarness(t, true)
			requireMemberRefusal(t, h.do(t, http.MethodPost, tc.path, tc.token, tc.body), tc.name)
			if n := len(h.codex.calls()) + len(h.claude.calls()); n != 0 {
				t.Fatalf("%d executor calls, want none", n)
			}
		})
	}
}

// R2-3: stripping the image tool from an allowed_tools choice keeps the other tools it allows.
func TestSessionMemberGateR2StrippingKeepsTheOtherAllowedTools(t *testing.T) {
	h := newMemberGateHarness(t, true)
	u := useRealExecutor(t, h, "codex")
	body := `{"model":"gpt-6-astra","input":"hi","tools":[{"type":"image_generation"},{"type":"function","name":"f","parameters":{"type":"object"}}],"tool_choice":{"type":"allowed_tools","mode":"required","tools":[{"type":"image_generation"},{"type":"function","name":"f"}]}}`
	if r := h.do(t, http.MethodPost, "/v1/responses", codexSessionToken, body); r.Code != http.StatusOK {
		t.Fatalf("HTTP=%d body %s", r.Code, r.Body.String())
	}
	got := u.received()
	if len(got) != 1 {
		t.Fatalf("upstream calls = %d, want 1", len(got))
	}
	if bytes.Contains(got[0], []byte("image_generation")) {
		t.Fatalf("the image tool reached the upstream: %s", got[0])
	}
	if gjson.GetBytes(got[0], "tool_choice.type").String() != "allowed_tools" ||
		gjson.GetBytes(got[0], "tool_choice.tools.#").Int() != 1 ||
		gjson.GetBytes(got[0], "tool_choice.tools.0.name").String() != "f" {
		t.Fatalf("tool_choice = %s, want allowed_tools naming f alone", gjson.GetBytes(got[0], "tool_choice").Raw)
	}
}

// R2-1 control: with response steering on, the gate refuses only what it must; a member's follow-up frames still run.
func TestSessionMemberGateR2DuplexMemberFramesStillRun(t *testing.T) {
	h := newMemberGateHarness(t, true)
	h.server.cfg.Codex.ResponseSteering = true
	h.server.cfg.CodexResponseSteering = true
	h.server.handlers.Cfg.CodexResponseSteering = true
	var mu sync.Mutex
	var frames [][]byte
	upstream := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		c, err := (&websocket.Upgrader{}).Upgrade(w, r, nil)
		if err != nil {
			t.Error(err)
			return
		}
		defer func() { _ = c.Close() }()
		_ = c.SetReadDeadline(time.Now().Add(10 * time.Second))
		for n := 1; ; n++ {
			_, p, err := c.ReadMessage()
			if err != nil {
				return
			}
			mu.Lock()
			frames = append(frames, append([]byte(nil), p...))
			mu.Unlock()
			_ = c.WriteMessage(websocket.TextMessage, []byte(fmt.Sprintf(`{"type":"response.created","response":{"id":"r%d","output":[]}}`, n)))
			_ = c.WriteMessage(websocket.TextMessage, []byte(fmt.Sprintf(`{"type":"response.completed","response":{"id":"r%d","output":[]}}`, n)))
		}
	}))
	defer upstream.Close()
	h.server.handlers.AuthManager.RegisterExecutor(runtimeexec.NewCodexAutoExecutor(h.server.cfg))
	if _, err := h.server.handlers.AuthManager.Register(context.Background(), &auth.Auth{ID: "member-gate-codex", Provider: "codex", Status: auth.StatusActive, Attributes: map[string]string{"api_key": "FAKE_UPSTREAM_KEY", "base_url": upstream.URL, "websockets": "true"}}); err != nil {
		t.Fatal(err)
	}
	c := dialMemberGateWebsocket(t, h, "/v1/responses", codexSessionToken)
	for i, frame := range []string{
		`{"type":"response.create","model":"gpt-6-astra","input":[]}`,
		`{"type":"response.create","model":"gpt-6-astra","input":[{"role":"user","content":"again"}]}`,
	} {
		if err := c.WriteMessage(websocket.TextMessage, []byte(frame)); err != nil {
			t.Fatal(err)
		}
		if v := nextTerminalEvent(t, c); gjson.GetBytes(v, "type").String() != "response.completed" {
			t.Fatalf("member frame %d: %s", i+1, v)
		}
	}
	mu.Lock()
	n := len(frames)
	mu.Unlock()
	if n != 2 {
		t.Fatalf("upstream frames = %d, want 2", n)
	}
}
